<?php require_once __DIR__.'/../config/config.php';$u=role_required(['editor','managing_editor']);$pageTitle='Editor Dashboard';$pdo=db();$id=(int)$u['id'];$c=[['Assigned',(int)$pdo->query("SELECT COUNT(*) FROM manuscripts WHERE assigned_editor_id=$id")->fetchColumn()],['Review',(int)$pdo->query("SELECT COUNT(*) FROM manuscripts WHERE assigned_editor_id=$id AND status IN ('UNDER_REVIEW','SECOND_REVIEW')")->fetchColumn()],['Revision',(int)$pdo->query("SELECT COUNT(*) FROM manuscripts WHERE assigned_editor_id=$id AND status='REVISION_REQUIRED'")->fetchColumn()],['Accepted',(int)$pdo->query("SELECT COUNT(*) FROM manuscripts WHERE assigned_editor_id=$id AND status='ACCEPTED'")->fetchColumn()]];include __DIR__.'/../includes/header.php';?><h1 class="title">Editor Dashboard</h1><div class="cards"><?php foreach($c as $x):?><div class="card"><div class="muted"><?=e($x[0])?></div><div class="n"><?=$x[1]?></div></div><?php endforeach;?></div><div class="panel"><a class="btn primary" href="<?=BASE_URL?>editor/manuscripts.php">Manage Manuscripts</a></div><?php include __DIR__.'/../includes/footer.php';?>